									'GiftCert',
									'Subtotal',
									'Service',
									'ShipItem',
									'TaxItem',
									'InvtPart',
									'Payment',
									'Expense',
									'NonInvtPart',
									'TaxGroup',
									'Kit',
									'Markup',
									'DwnLdItem',
									'OthCharge',
									'Assembly',
									'SubscriPlan',
